// Generated by `hale api client --surface Orders --lang ts` from the rows of the surface
// Orders (fnv1a64:9a75ae7111b187d5). Do not edit: regenerate it, and `hale api client --check` refuses a
// copy whose digest is no longer the surface's. See spec/api.md § The clients.
//
// One async function per member, `<locus><Fn>(opts, request)`, answering the tagged union of
// `result`, `handler_error`, `refusal` and `server_error`; a connection that never answered is
// thrown as a TransportError. A quantity, an identity or a range crosses as the number it counts
// (an Int past 2^53 loses precision as a JSON number does in JavaScript).

export const SURFACE = "Orders";
export const SURFACE_DIGEST = "fnv1a64:9a75ae7111b187d5";

// ---- the wire, as every client of a surface speaks it (spec/api.md § The clients) ----
//
// Depends on `fetch` and `WebSocket` and nothing else. An endpoint is
// `http://host:port` for a member's call and `ws://host:port` (a hub) for a
// stream; a socket is not spoken (`fetch` has none). A call sends its
// member's digest in `Hale-Surface-Digest` (which a surface that has since
// gained members still admits) and answers one of four outcomes;
// the fifth, a connection that never answered, is thrown as a TransportError,
// because a request that may have been accepted is not a refusal.

// The globals the wire names as types, reached through `globalThis` so that no type of the surface (a
// `Response`, a `Record`, a `Promise`) can shadow one: a module's own declarations win over the
// global scope, and `globalThis.X` is the one spelling they do not reach.
type __Record<K extends keyof any, V> = globalThis.Record<K, V>;
type __Promise<T> = globalThis.Promise<T>;
type __Array<T> = globalThis.Array<T>;
type __AsyncIterable<T> = globalThis.AsyncIterable<T>;
type __AsyncGenerator<T> = globalThis.AsyncGenerator<T>;
type __Response = globalThis.Response;
type __MessageEvent = globalThis.MessageEvent;

export interface ClientOptions {
  /** `http://host:port` of an `http::Rpc` listener (or of a hub's listener). */
  endpoint: string;
  /** The bearer token, sent as `Authorization: Bearer`. */
  bearer?: string;
  /** A `fetch` to use instead of the global one. */
  fetch?: typeof fetch;
}

export interface StreamOptions {
  /** `ws://host:port` of a hub. */
  endpoint: string;
  /** The bearer token, sent as `?access_token=` (a browser cannot set a header on a WebSocket). */
  bearer?: string;
  /** A `WebSocket` constructor to use instead of the global one. */
  WebSocket?: typeof WebSocket;
}

/** A refusal: the request was not run (spec/api.md § Outcomes). */
export interface Refusal {
  /** `malformed`, `digest_mismatch`, `unauthenticated`, `unauthorized`, `full`, `shutting_down` or `unavailable`. */
  kind: string;
  reason: string;
  /** The roles a refused row requires. */
  requires: string[];
  /** The digest the server holds, for `digest_mismatch`. */
  served?: string;
}

/** The connection ended, or answered no outcome: the request may or may not have run. */
export class TransportError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TransportError";
  }
}

export type __Outcome<T, E> =
  | { kind: "result"; value: T }
  | { kind: "handler_error"; error: E }
  | { kind: "refusal"; refusal: Refusal }
  | { kind: "server_error" };

function __apiRefusal(body: unknown): Refusal {
  const r = (body as { refusal?: __Record<string, unknown> } | null)?.refusal ?? {};
  const out: Refusal = {
    kind: typeof r.kind === "string" ? r.kind : "malformed",
    reason: typeof r.reason === "string" ? r.reason : "",
    requires: Array.isArray(r.requires) ? r.requires.map(String) : [],
  };
  if (typeof r.served === "string") out.served = r.served;
  return out;
}

async function __apiCall<T, E>(
  opts: ClientOptions,
  member: string,
  digest: string,
  payload: string,
  decodeValue: (json: unknown) => T,
  decodeError: (json: unknown) => E,
): __Promise<__Outcome<T, E>> {
  const headers: __Record<string, string> = {
    "Content-Type": "application/json",
    "Hale-Surface-Digest": digest,
  };
  if (opts.bearer) headers["Authorization"] = "Bearer " + opts.bearer;
  let res: __Response;
  let text: string;
  try {
    res = await (opts.fetch ?? fetch)(opts.endpoint + "/call/" + member, { method: "POST", headers, body: payload });
    text = await res.text();
  } catch (e) {
    throw new TransportError("the endpoint " + opts.endpoint + " cannot be reached: " + String(e));
  }
  let body: unknown = null;
  try {
    body = text.length > 0 ? JSON.parse(text) : null;
  } catch {
    throw new TransportError("the endpoint answered " + res.status + " with no JSON: " + text);
  }
  if (res.status === 200) return { kind: "result", value: decodeValue(body) };
  if (res.status === 422) return { kind: "handler_error", error: decodeError(body) };
  // a classed handler error names its class (spec/api.md § Error classes)
  if (res.headers.get("Hale-Error-Class") !== null) return { kind: "handler_error", error: decodeError(body) };
  const refusal = __apiRefusal(body);
  if ((body as { refusal?: unknown } | null)?.refusal === undefined) {
    throw new TransportError("the endpoint answered " + res.status + " with no outcome: " + text);
  }
  if (refusal.kind === "server") return { kind: "server_error" };
  return { kind: "refusal", refusal };
}

/** The description the endpoint serves this caller, as parsed JSON. */
export async function describe(opts: ClientOptions): __Promise<unknown> {
  const headers: __Record<string, string> = { Accept: "application/json" };
  if (opts.bearer) headers["Authorization"] = "Bearer " + opts.bearer;
  try {
    const res = await (opts.fetch ?? fetch)(opts.endpoint + "/.description", { headers });
    return JSON.parse(await res.text());
  } catch (e) {
    throw new TransportError("the description of " + opts.endpoint + " cannot be read: " + String(e));
  }
}

// ---- streams over a hub ----

/** What a subscription yields; it ends after `refusal`, `expired`, `revoked` or `closed`. */
export type __StreamEvent<P> =
  | { kind: "subscribed" }
  | { kind: "event"; seq: number; payload: P }
  | { kind: "refusal"; refusal: Refusal }
  | { kind: "expired" }
  | { kind: "revoked" }
  | { kind: "closed" };

export interface __Subscription<P> extends __AsyncIterable<__StreamEvent<P>> {
  /** Ends the subscription and closes the connection. */
  close(): void;
}

function __apiSubscribe<P>(opts: StreamOptions, topic: string, decode: (json: unknown) => P): __Subscription<P> {
  const queue: __Array<__StreamEvent<P> | TransportError | null> = [];
  let wake: (() => void) | undefined;
  let ended = false;
  const push = (item: __StreamEvent<P> | TransportError | null): void => {
    queue.push(item);
    if (wake) {
      const w = wake;
      wake = undefined;
      w();
    }
  };
  const url = new URL(opts.endpoint);
  if (opts.bearer) url.searchParams.set("access_token", opts.bearer);
  const ws = new (opts.WebSocket ?? WebSocket)(url.toString());
  const finish = (): void => {
    if (ended) return;
    ended = true;
    push(null);
    try {
      ws.close();
    } catch {
      /* already closed */
    }
  };
  const lose = (why: string): void => {
    if (ended) return;
    ended = true;
    push(new TransportError(why));
    push(null);
  };
  ws.onopen = () => ws.send(JSON.stringify({ type: "subscribe", topic }));
  ws.onmessage = (m: __MessageEvent) => {
    if (ended) return;
    let frame: __Record<string, unknown>;
    try {
      frame = JSON.parse(String(m.data)) as __Record<string, unknown>;
    } catch {
      return lose("the hub sent a frame that is not JSON: " + String(m.data));
    }
    if (frame.type !== "closed" && frame.topic !== undefined && frame.topic !== topic) return;
    switch (frame.type) {
      case "subscribed":
        return push({ kind: "subscribed" });
      case "event":
        return push({ kind: "event", seq: Number(frame.seq), payload: decode(frame.payload) });
      case "refusal":
        push({ kind: "refusal", refusal: __apiRefusal(frame) });
        return finish();
      case "unauthorized":
        push({ kind: frame.reason === "expired" ? "expired" : "revoked" });
        return finish();
      case "closed":
        push({ kind: "closed" });
        return finish();
      default:
        return;
    }
  };
  ws.onerror = () => lose("the hub at " + opts.endpoint + " cannot be reached");
  ws.onclose = () => lose("the hub ended the connection with no closed frame");
  return {
    close: finish,
    async *[Symbol.asyncIterator](): __AsyncGenerator<__StreamEvent<P>> {
      for (;;) {
        while (queue.length === 0) await new Promise<void>((resolve) => (wake = resolve));
        const item = queue.shift();
        if (item === null || item === undefined) return;
        if (item instanceof TransportError) throw item;
        yield item;
      }
    },
  };
}

/**
 * Why an order was not placed.
 *
 * `UnknownSymbol`: No instrument has the symbol.
 * `Closed`: The desk is closed for the day.
 */
export type OrderError = "UnknownSymbol" | "Closed" | { Rejected: string };

export function encode_OrderError(v: OrderError): unknown {
  if (typeof v === "string") return v;
  if ("Rejected" in v) return { Rejected: v.Rejected };
  return v;
}

export function decode_OrderError(json: unknown): OrderError {
  if (typeof json === "string") return (json as OrderError);
  const o = ((json ?? {}) as __Record<string, unknown>);
  if ("Rejected" in o) return { Rejected: String(o["Rejected"] ?? "") };
  return (json as OrderError);
}

/**
 * Where an order came from.
 *
 * `Desk`: Typed by a person.
 */
export type Origin = "Desk" | "Api";

export function encode_Origin(v: Origin): unknown {
  return v;
}

export function decode_Origin(json: unknown): Origin {
  return (json as Origin);
}

/**
 * A request to place an order.
 *
 * The desk fills it at the limit or better.
 */
export interface PlaceOrder {
  /** The instrument's ticker symbol. */
  symbol: string;
  /** How many units to buy. */
  qty: number;
  /** An amount of money, counted in cents. */
  limit: number;
  /** Where the order came from. */
  origin: Origin;
}

export function encode_PlaceOrder(v: PlaceOrder): unknown {
  return {
    symbol: v.symbol,
    qty: v.qty,
    limit: v.limit,
    origin: encode_Origin(v.origin),
  };
}

export function decode_PlaceOrder(json: unknown): PlaceOrder {
  const o = (json ?? {}) as __Record<string, unknown>;
  return {
    symbol: String(o["symbol"] ?? ""),
    qty: Number(o["qty"] ?? 0),
    limit: Number(o["limit"] ?? 0),
    origin: decode_Origin(o["origin"]),
  };
}

/** What the desk did with an order. */
export interface Receipt {
  /** The order's number on the desk. */
  order: number;
  /** An amount of money, counted in cents. */
  notional: number;
}

export function encode_Receipt(v: Receipt): unknown {
  return {
    order: v.order,
    notional: v.notional,
  };
}

export function decode_Receipt(json: unknown): Receipt {
  const o = (json ?? {}) as __Record<string, unknown>;
  return {
    order: Number(o["order"] ?? 0),
    notional: Number(o["notional"] ?? 0),
  };
}

export interface Ticket {
  order: number;
}

export function encode_Ticket(v: Ticket): unknown {
  return {
    order: v.order,
  };
}

export function decode_Ticket(json: unknown): Ticket {
  const o = (json ?? {}) as __Record<string, unknown>;
  return {
    order: Number(o["order"] ?? 0),
  };
}

/** Desk::cancel */
export type DeskCancelOutcome = __Outcome<Ticket, never>;

/** Cancel an order. */
export function deskCancel(opts: ClientOptions, request: Ticket): __Promise<DeskCancelOutcome> {
  return __apiCall(opts, "Desk::cancel", "fnv1a64:13ee0952e84c2ee1", JSON.stringify(encode_Ticket(request)), (json) => decode_Ticket(json), () => { throw new TransportError("the member has no handler error, and one came"); });
}

/** Desk::count */
export type DeskCountOutcome = __Outcome<number, never>;

export function deskCount(opts: ClientOptions, request: Ticket): __Promise<DeskCountOutcome> {
  return __apiCall(opts, "Desk::count", "fnv1a64:8bcb2e80431bc3b4", JSON.stringify(encode_Ticket(request)), (json) => Number(json ?? 0), () => { throw new TransportError("the member has no handler error, and one came"); });
}

/** Desk::place, requires clerk */
export type DeskPlaceOutcome = __Outcome<Receipt, OrderError>;

/**
 * Place an order.
 * It is filled at the limit or better; a desk that is closed refuses it.
 */
export function deskPlace(opts: ClientOptions, request: PlaceOrder): __Promise<DeskPlaceOutcome> {
  return __apiCall(opts, "Desk::place", "fnv1a64:cd8504051ff3f597", JSON.stringify(encode_PlaceOrder(request)), (json) => decode_Receipt(json), (json) => decode_OrderError(json));
}
